{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 OverTop\par}
{\pard \ql \f0 \sa180 \li0 \fi0 3-Band Upward and Downward Multiband Dynamics Processor (OTT style) for aggressive presence, punch, and detail leveling.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Features\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab 3-band split crossover (88 Hz and 2.5 kHz) with independent upward and downward compression engines\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Interactive threshold bar editing: drag horizontally to shift thresholds per band\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Per-band bypass switches and dedicated band output gain trims\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Global Depth, Time scaling, and In/Out gain controls\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Dedicated Upward % and Downward % intensity knobs\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Modern animated vector UI with real-time level meters and gain reduction traces\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Scalable HiDPI text zoom (100% - 140%)\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 PulseDuck\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Multiband sidechain volume shaper and rhythmic ducking engine with custom breakpoint curve editing, real-time kick overlay scope, and automatic sidechain tracing.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Features\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab 16 Instant Curve Presets plus custom multi-node breakpoint envelope editor with tension control\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab 4 Flexible Trigger Modes: Tempo Sync (Repeat), MIDI Note, External Sidechain (Ch 3/4), and Audio Input\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Multiband Crossover: Full-band, 2-band (Lo/Hi), and 3-band (Lo/Mid/Hi) ducking with 12/24 dB slopes and Band Solo\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Real-time Dual Oscilloscope displaying ducked audio (white) alongside incoming sidechain trigger (yellow)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab One-click TRACE SC: Automatically captures and fits the ducking envelope around your kick drum transient\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Variable Curve Slope and Timing Shift (<< < > >>) to dial in the groove and lock the pocket\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Audio trigger filter, threshold, hold-off, and MIDI velocity sensitivity\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Scalable HiDPI text zoom (100% - 140%)\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 SpectralCarver\par}
{\pard \ql \f0 \sa180 \li0 \fi0 32-Band Dynamic Spectral Ducker using Cytomic SVF filters.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Features\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab 32-band Cytomic SVF dynamic spectral ducking\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab High-contrast visualizer with smooth animated controls and hover halos\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Stereo (L/R) and Mid/Side (M/S) processing modes\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Low-cut and high-cut sidechain filtering with interactive spectrum display\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Sidechain audition mode, freeze function, and scalable UI text zoom\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Safe ceiling and NaN/Inf protection\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Routing\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Route sidechain control audio to Channels 3/4.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 ConsoleQ\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Hybrid Console Channel Strip Equalizer with E/G series curves, high-headroom Air Band, Sub weight, and real-time FFT spectrum analyzer.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Features\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab 4-Band Console EQ (LF, LMF, HMF, HF) with switchable Bell/Shelf modes on LF and HF\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab 18 dB/oct HPF (20 - 500 Hz) and 12 dB/oct LPF (3k - 22 kHz) console filters\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab High-headroom Air Band with selectable frequencies (2.5k, 5k, 10k, 20k, 40 kHz) and Sub 10Hz resonance control\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Switchable E-Series (Constant Q) and G-Series (Proportional Q) EQ topologies\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Analog character modes: Clean, Subtle, and Warm saturation\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Interactive draggable EQ nodes directly on the curve display\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Real-time 2048-point FFT Spectrum Analyzer (Post-EQ, Pre-EQ, or Off)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Momentary band solo auditioning per frequency band\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Output stage with M/S stereo width (0-200%), panning, auto-gain, and latched peak LED\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Scalable HiDPI text zoom (100% - 140%)\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 PocketQ\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Compact, ultra-low CPU console channel strip equalizer with fixed musical frequencies, E/G curves, and high-headroom Air Band.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Features\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Fixed musical frequency bands: Sub (10 Hz), 40 Hz, 160 Hz, 650 Hz, and 2.5 kHz (switchable Shelf/Bell)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab High-headroom Air Band shelf with selectable frequencies (2.5k, 5k, 10k, 20k, 40 kHz)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab 18 dB/oct HPF and 12 dB/oct LPF console cut filters\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab E-Series (tight constant Q) and G-Series (smooth proportional Q) response curves\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Console Drive switch with Clean and Warm analog saturation\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Auto-gain compensation and phase invert toggle\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Ultra-lightweight DSP footprint optimized for loading across every mixer track\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Scalable HiDPI text zoom (100% - 140%)\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
