{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 \u55357 ?\u56514 ? Repository Structure\par}
{\pard \ql \f0 \sa180 \li0 \fi0 ReaPack uses directory structure to organize categories in REAPER's package browser:\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \f1 .\line
\u9500 ?\u9472 ?\u9472 ? .github/\line
\u9474 ?   \u9492 ?\u9472 ?\u9472 ? workflows/\line
\u9474 ?       \u9500 ?\u9472 ?\u9472 ? deploy.yml          # Automatically regenerates index.xml on push\line
\u9474 ?       \u9492 ?\u9472 ?\u9472 ? check.yml           # Validates package headers on PRs/pushes\line
\u9500 ?\u9472 ?\u9472 ? .reapack-index.conf         # reapack-index options\line
\u9500 ?\u9472 ?\u9472 ? index.xml                   # ReaPack package index file\line
\u9500 ?\u9472 ?\u9472 ? README.md                   # Repository documentation (shown in ReaPack)\line
\u9500 ?\u9472 ?\u9472 ? screenshots/                # Plugin screenshot previews (WebP)\line
\u9500 ?\u9472 ?\u9472 ? Creative/                   # ReaPack Category: Creative\line
\u9474 ?   \u9500 ?\u9472 ?\u9472 ? ChronoWarp.jsfx         # JSFX plugin with ReaPack metadata header\line
\u9474 ?   \u9492 ?\u9472 ?\u9472 ? VintageFlux.jsfx        # JSFX plugin with ReaPack metadata header\line
\u9500 ?\u9472 ?\u9472 ? Delay/                      # ReaPack Category: Delay\line
\u9474 ?   \u9492 ?\u9472 ?\u9472 ? EchoForge.jsfx          # JSFX plugin with ReaPack metadata header\line
\u9500 ?\u9472 ?\u9472 ? Dynamics/                   # ReaPack Category: Dynamics\line
\u9474 ?   \u9500 ?\u9472 ?\u9472 ? Opto2A.jsfx             # JSFX plugin with ReaPack metadata header\line
\u9474 ?   \u9500 ?\u9472 ?\u9472 ? OverTop.jsfx            # JSFX plugin with ReaPack metadata header\line
\u9474 ?   \u9500 ?\u9472 ?\u9472 ? PulseDuck.jsfx          # JSFX plugin with ReaPack metadata header\line
\u9474 ?   \u9492 ?\u9472 ?\u9472 ? SpectralCarver.jsfx     # JSFX plugin with ReaPack metadata header\line
\u9500 ?\u9472 ?\u9472 ? EQ/                         # ReaPack Category: EQ\line
\u9474 ?   \u9500 ?\u9472 ?\u9472 ? ConsoleQ.jsfx           # JSFX plugin with ReaPack metadata header\line
\u9474 ?   \u9492 ?\u9472 ?\u9472 ? PocketQ.jsfx            # JSFX plugin with ReaPack metadata header\line
\u9492 ?\u9472 ?\u9472 ? Saturation/                 # ReaPack Category: Saturation\line
    \u9500 ?\u9472 ?\u9472 ? OInflator.jsfx          # JSFX plugin with ReaPack metadata header\line
    \u9492 ?\u9472 ?\u9472 ? Phoenix.jsfx            # JSFX plugin with ReaPack metadata header\par}
